{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.category_date_wise_data as WITH base_sales AS ( SELECT date, UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' WHEN type = \'Store\' THEN \'Offline\' END AS channel, SUM(gross_sales::INT) AS gross_sales_value, SUM(gross_quantity::INT) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1,2,3 ) , mrp_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(sku, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(sku, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, avg(MRP) MRP FROM snitch_db.maplemonk.logic_final_item_master WHERE BRAND = \'SNITCH\' Group by 1 ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, MAX(l1_category) AS l1_category, MAX(category) AS category, MAX(meta1) AS meta1, MAX(meta2) AS meta2, MAX(meta3) AS meta3, max(cogs) cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ),temp as (with a as (select LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' in REVERSE(value:sku::STRING))) as sku_group from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value) select UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, from a),as_of AS ( SELECT CURRENT_DATE() AS as_of_date ), inv_current_by_sku AS ( SELECT UPPER( IFF( UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(s.sku_group, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(s.sku_group, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, sum(COALESCE(qty_available, 0)+COALESCE(qty_offline_available, 0)+COALESCE(qty_jit, 0)) AS inv_current, sum(COALESCE(qty_available, 0)) AS online_inv_current, sum(COALESCE(qty_offline_available, 0)+COALESCE(qty_jit, 0)) AS offline_inv_current, sum(qty_bad_inventory) bad_inv, sum(qty_blocked) blocked_inv FROM snitch_db.maplemonk.cogs_daily_snapshot s WHERE s.date = CURRENT_DATE() -1 GROUP BY 1 ), inward_lots AS ( SELECT UPPER( IFF( UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, p.\"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(p.\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking p WHERE LOWER(p.final_type) = \'new inward\' GROUP BY 1,2 ), inward_lots_fifo AS ( SELECT il.*, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_inward_qty, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - inward_qty AS cum_inward_qty_prev FROM inward_lots il ), inward_total AS ( SELECT sku_group_clean, SUM(inward_qty) AS total_inward_qty FROM inward_lots GROUP BY 1 ), fifo_remaining_by_lot AS ( SELECT f.sku_group_clean, f.inward_date, f.inward_qty, ic.inv_current, ic.online_inv_current, ic.offline_inv_current, ic.bad_inv, ic.blocked_inv, it.total_inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) AS consumed_qty, GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) - f.cum_inward_qty_prev ), 0 ) AS consumed_in_lot, GREATEST( f.inward_qty - GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) - f.cum_inward_qty_prev ), 0 ), 0 ) AS remaining_qty, DATEDIFF(\'day\', f.inward_date, CURRENT_DATE()) AS lot_age_days FROM inward_lots_fifo f LEFT JOIN inv_current_by_sku ic ON f.sku_group_clean = ic.sku_group_clean LEFT JOIN inward_total it ON f.sku_group_clean = it.sku_group_clean ), inv_ageing_fifo AS ( SELECT sku_group_clean, MAX(inv_current) AS inv_current, max(online_inv_current) online_inv_current, max(offline_inv_current) offline_inv_current, max(bad_inv) bad_inv, max(blocked_inv) blocked_inv, SUM(remaining_qty) AS remaining_qty_total, CASE WHEN SUM(remaining_qty) = 0 THEN 0 ELSE SUM(remaining_qty * lot_age_days) / NULLIF(SUM(remaining_qty),0) END AS weighted_age_days FROM fifo_remaining_by_lot GROUP BY 1 ) , inv_ageing as (SELECT sku_group_clean , inv_current, remaining_qty_total, weighted_age_days, online_inv_current,offline_inv_current,bad_inv,blocked_inv, CASE WHEN weighted_age_days <= 30 THEN \'0-30\' WHEN weighted_age_days <= 60 THEN \'30-60\' WHEN weighted_age_days <= 90 THEN \'60-90\' WHEN weighted_age_days <= 120 THEN \'90-120\' WHEN weighted_age_days <= 180 THEN \'120-180\' WHEN weighted_age_days <= 270 THEN \'180-270\' WHEN weighted_age_days <= 360 THEN \'270-360\' ELSE \'360+\' END AS inventory_ageing_bucket FROM inv_ageing_fifo) SELECT bs.date, bs.channel, ia.inventory_ageing_bucket, coalesce(bs.sku_group_clean,ia.sku_group_clean) AS sku_group, max(mm.l1_category) l1_category, max(mm.category) category, max(mm.meta1) meta1, max(mm.meta2) meta2, max(mm.meta3) meta3, max(mm.cogs) cogs, avg(mrp.MRP) mrp, SUM(bs.gross_sales_value) AS gross_sales_value, SUM(bs.qty * mrp.MRP) AS mrp_value, SUM(bs.qty) AS qty, SUM(bs.qty * mm.cogs) AS cogs_sold FROM base_sales bs full outer join inv_ageing ia using(sku_group_clean) LEFT JOIN mrp_map mrp using(sku_group_clean) LEFT JOIN meta_map mm using(sku_group_clean) group by 1,2,3,4 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            